--!strict
-- Explorer: ReplicatedStorage.BabyBeastsShared.GameEgg
-- Egg meshes from the Steal An Egg reference. Mesh asset ids already load in this place.
-- Models in Missing have no MeshPart (union geometry was stripped from the place file).
-- Which eggs spawn in which biome lives in EggSources.Biomes.

export type EggPart = {
	Name: string,
	MeshId: string,
	Size: Vector3,
	Color: Color3,
	Transparency: number,
	Offset: CFrame,
	TextureId: string?,
	Shape: string?, -- "Block": a plain Plastic Part with stud surfaces instead of a mesh
	SideSurface: string?, -- Block side faces: an Enum.SurfaceType name (top is Studs, bottom Inlet)
}

export type Egg = {
	Name: string,
	MeshId: string,
	Parts: { EggPart },
	Center: Vector3,
	Bounds: Vector3,
}

