local DEFAULT_PROFILE: EggProfile = {
	Class = "Medium",
	Penalty = 0.8,
	HeightMin = 0.9,
	HeightMax = 1.15,
	Income = 8,
}

local GameEgg = {}

-- Pets without a Steal An Egg egg get a generated one from the pet catalog (built on first use).
local generated: { [string]: Egg | false } = {}

-- Cozy Backyard eggs: classic Roblox bricks. A stepped stack of Plastic blocks (studs on top,
-- each egg its own side-stud variant) in the pet's colours, with a few blocky pet details.
type BlockyStyle = {
	Base: Color3,
	Band: Color3,
	Cap: Color3,
	Sides: string,
	Extras: { { Vector3 | Color3 } }?, -- { offset (tier space, y from the floor), size, colour }
}

local function rgb(r: number, g: number, b: number): Color3
	return Color3.fromRGB(r, g, b)
end

