-- {width, height} of each tier, bottom to top, as fractions of the egg's 4 x 6 stud box.
local TIERS = { { 0.66, 0.15 }, { 0.92, 0.16 }, { 1.0, 0.17 }, { 0.92, 0.15 }, { 0.76, 0.14 }, { 0.56, 0.12 }, { 0.32, 0.11 } }
local BLOCKY_W, BLOCKY_H = 4, 6

local function blockyEgg(name: string, style: BlockyStyle): Egg
	local parts: { EggPart } = {}
	local function block(partName: string, center: Vector3, size: Vector3, color: Color3)
		table.insert(parts, {
			Name = partName,
			MeshId = "",
			Shape = "Block",
			SideSurface = style.Sides,
			Size = size,
			Color = color,
			Transparency = 0,
			Offset = CFrame.new(center),
		})
	end
	local y = 0
	for index, tier in TIERS do
		local w, h = tier[1] * BLOCKY_W, tier[2] * BLOCKY_H
		local color = if index == #TIERS then style.Cap elseif index == 2 or index == 5 then style.Band else style.Base
		block("Tier" .. index, Vector3.new(0, y + h * 0.5, 0), Vector3.new(w, h, w), color)
		y += h
	end
	local top = y
	for index, extra in style.Extras or {} do
		local offset, size, color = extra[1] :: Vector3, extra[2] :: Vector3, extra[3] :: Color3
		block("Detail" .. index, offset, size, color)
		top = math.max(top, offset.Y + size.Y * 0.5)
	end
	local minX, maxX, minZ, maxZ = -BLOCKY_W * 0.5, BLOCKY_W * 0.5, -BLOCKY_W * 0.5, BLOCKY_W * 0.5
	for _, part in parts do
		local p, half = part.Offset.Position, part.Size * 0.5
		minX, maxX = math.min(minX, p.X - half.X), math.max(maxX, p.X + half.X)
		minZ, maxZ = math.min(minZ, p.Z - half.Z), math.max(maxZ, p.Z + half.Z)
	end
	return {
		Name = name .. " Egg",
		MeshId = "",
		Center = Vector3.new((minX + maxX) * 0.5, top * 0.5, (minZ + maxZ) * 0.5),
		Bounds = Vector3.new(maxX - minX, top, maxZ - minZ),
		Parts = parts,
	}
end

local function catalogEgg(name: string): Egg?
	local cached = generated[name]
	if cached ~= nil then
		return cached or nil
	end
	local PetCatalog = require(script.Parent.PetCatalog) :: any
	local entry = PetCatalog.get(name)
	local spec = entry and entry.Egg
	local egg: Egg? = nil
	local style = entry and BLOCKY[entry.GameName]
	if style then
		egg = blockyEgg(entry.GameName, style)
	elseif spec and spec.Mesh ~= 0 then
		local meshId = "rbxassetid://" .. spec.Mesh
		egg = {
			Name = entry.GameName .. " Egg",
			MeshId = meshId,
			Center = Vector3.zero,
			Bounds = spec.Size,
			Parts = {
				{
					Name = "Shell",
					MeshId = meshId,
					TextureId = if spec.Texture ~= 0 then "rbxassetid://" .. spec.Texture else nil,
					Size = spec.Size,
					Color = Color3.new(1, 1, 1),
					Transparency = 0,
					Offset = CFrame.identity,
				},
			},
		}
	end
	generated[name] = egg or false
	return egg
end

function GameEgg.get(name: string): Egg?
	return ByName[name] or ByName[name .. " Egg"] or catalogEgg(name)
end

function GameEgg.profile(name: string): EggProfile
	return Profile[name] or DEFAULT_PROFILE
end

GameEgg.Eggs = Eggs
GameEgg.Missing = Missing
GameEgg.ByName = ByName

return GameEgg
